SET NOCOUNT ON;
DECLARE @tag nvarchar(100)=N'REPORT_NOON_20261106',@ns varchar(15)=(SELECT maNV FROM TaiKhoan WHERE tenTK='hieu.nhasi');
IF (SELECT COUNT(*) FROM PhieuKham p JOIN LichHen h ON h.maLH=p.maLH WHERE h.maNV=@ns AND p.ngayLap>='20261106' AND p.ngayLap<'20261107' AND p.trangThai='HOAN_TAT')<>3 THROW 52000,N'Chưa đủ 3 lượt hoàn tất nha sĩ demo.',1;
IF (SELECT SUM(ct.thanhTien) FROM ChiTietPhieuKham ct JOIN PhieuKham p ON p.maPK=ct.maPK JOIN LichHen h ON h.maLH=p.maLH WHERE h.maNV=@ns AND p.ngayLap>='20261106' AND p.ngayLap<'20261107' AND p.trangThai='HOAN_TAT')<>2580000 THROW 52001,N'Sai thống kê cá nhân.',1;
IF EXISTS(SELECT 1 FROM PhieuKham p LEFT JOIN LichHen h ON h.maLH=p.maLH WHERE p.loiDan LIKE @tag+'%' AND (p.ngayLap>'20261106 13:00' OR (p.trangThai='HOAN_TAT' AND h.trangThai<>'HOAN_TAT') OR (p.trangThai IN ('CHO_KHAM','DANG_KHAM') AND h.trangThai<>'DA_DEN'))) THROW 52002,N'Phiếu sai mốc giờ hoặc trạng thái lịch.',1;
IF EXISTS(SELECT 1 FROM HoaDon hd JOIN PhieuKham p ON p.maPK=hd.maPK WHERE p.loiDan LIKE @tag+'%' AND (hd.maHD<>'HD'+SUBSTRING(p.maPK,3,13) OR hd.ngayLap>'20261106 13:00' OR hd.ngayThanhToan>'20261106 13:00')) THROW 52003,N'Hóa đơn sai mã hoặc mốc giờ.',1;
IF EXISTS(SELECT 1 FROM LichHen h JOIN DichVu d ON d.maDV=h.maDV WHERE (h.ghiChu LIKE @tag+'%' OR EXISTS(SELECT 1 FROM PhieuKham p WHERE p.maLH=h.maLH AND p.loiDan LIKE @tag+'%')) AND NOT EXISTS(SELECT 1 FROM LichLamViec v JOIN TaiKhoan t ON t.maNV=v.maNV WHERE v.maNV=h.maNV AND v.ngayTruc=CAST(h.ngayGioHen AS date) AND v.trangThai='DA_PHAN_CONG' AND t.vaiTro='NHASI' AND t.trangThai=1 AND CAST(h.ngayGioHen AS time)>=v.gioBatDau AND CAST(DATEADD(minute,d.thoiLuong,h.ngayGioHen) AS time)<=v.gioKetThuc)) THROW 52004,N'Lịch không có ca hợp lệ.',1;
IF EXISTS(SELECT 1 FROM LichHen h JOIN LichHen x ON h.maLH<>x.maLH JOIN DichVu d ON d.maDV=h.maDV JOIN DichVu dx ON dx.maDV=x.maDV WHERE h.ghiChu LIKE @tag+'%' AND h.trangThai NOT IN ('DA_HUY','KHONG_DEN') AND x.trangThai NOT IN ('DA_HUY','KHONG_DEN') AND ((h.maNV=x.maNV AND h.ngayGioHen<DATEADD(minute,dx.thoiLuong+15,x.ngayGioHen) AND x.ngayGioHen<DATEADD(minute,d.thoiLuong+15,h.ngayGioHen)) OR (h.maKH=x.maKH AND h.ngayGioHen<DATEADD(minute,dx.thoiLuong,x.ngayGioHen) AND x.ngayGioHen<DATEADD(minute,d.thoiLuong,h.ngayGioHen)))) THROW 52005,N'Trùng lịch/thiếu khoảng chuẩn bị.',1;
IF EXISTS(SELECT 1 FROM HoaDon hd JOIN PhieuKham p ON p.maPK=hd.maPK JOIN Voucher v ON v.maVoucher=hd.maVoucher WHERE p.loiDan LIKE @tag+'%' AND (v.trangThai<>1 OR CAST(hd.ngayLap AS date) NOT BETWEEN v.ngayBatDau AND v.ngayKetThuc OR hd.tongKhuyenMai<>50000)) THROW 52006,N'Voucher không hợp lệ.',1;
IF EXISTS(SELECT 1 FROM ChiTietPhieuKham ct JOIN PhieuKham p ON p.maPK=ct.maPK JOIN DichVu d ON d.maDV=ct.maDV JOIN LoaiDichVu l ON l.maLoaiDV=d.maLoaiDV WHERE p.loiDan LIKE @tag+'%' AND (ct.mucThueGTGT<>l.mucThueGTGT OR ct.donGia<>d.donGia OR d.trangThai<>1)) THROW 52007,N'Sai giá/thuế.',1;
IF EXISTS(SELECT 1 FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1) OR EXISTS(SELECT 1 FROM sys.triggers WHERE parent_class=1 AND is_disabled=1) THROW 52008,N'Ràng buộc chưa bật.',1;
SELECT h.trangThai,COUNT(*) so_luot FROM LichHen h WHERE CAST(h.ngayGioHen AS date)='20261106' GROUP BY h.trangThai;
SELECT h.maNV,p.trangThai,COUNT(*) so_phieu FROM PhieuKham p JOIN LichHen h ON h.maLH=p.maLH WHERE CAST(p.ngayLap AS date)='20261106' GROUP BY h.maNV,p.trangThai;
SELECT hd.maHD,p.maPK,h.maNV,hd.trangThai,hd.hinhThucThanhToan,hd.tongKhuyenMai,hd.ngayThanhToan FROM HoaDon hd JOIN PhieuKham p ON p.maPK=hd.maPK JOIN LichHen h ON h.maLH=p.maLH WHERE p.loiDan LIKE @tag+'%';
SELECT 'REPORT_NOON_VERIFIED' ketQua;
DBCC CHECKCONSTRAINTS WITH ALL_CONSTRAINTS;
